INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('d0792fc774983267f5ea','AMEDEX 2025 HEMAETOLOGY (2).pdf','142','Mixed/Unclassified','After flying from Sydney to Port Vila, a 25-year-
old man develops shortness of breath shortly
after landing. On further inquiry, you realize that
he is a known case of sickle cell trait, whose
father died of myocardial infarction at the age of
36 years. He denies any chest pain and muscle
and joint pain but feels slightly short of breath.
On examination, he has central cyanosis, a
blood pressure of 130/85 mmHg, a pulse of 110
bpm, and a respiratory rate of 24 breaths per
minute. He is afebrile. Pulse oximetry shows an
O2 saturation of 86% while on room air. The
rest of the exam, including a full neurological
exam, is inconclusive. Which one of the
following is the next best step in management?','{"A":"Start intravenous heparin\nimmediately.","B":"Do a chest X-ray to confirm","C":"pulmonary embolism.","D":"an EGG.","E":"Do CTPA to confirm pulmonary\nembolism."}','E',NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 HEMAETOLOGY (2).pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-4a209cc47007","duplicate_sources":[{"record_id":"d0792fc774983267f5ea","record_type":"text_mcq","source_file":"AMEDEX 2025 HEMAETOLOGY (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 HEMAETOLOGY (2).pdf","source_page":142,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"d0792fc774983267f5ea","source_file":"AMEDEX 2025 HEMAETOLOGY (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 HEMAETOLOGY (2).pdf","source_year":2025,"source_page":142,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"After flying from Sydney to Port Vila, a 25-year-\nold man develops shortness of breath shortly\nafter landing. On further inquiry, you realize that\nhe is a known case of sickle cell trait, whose\nfather died of myocardial infarction at the age of\n36 years. He denies any chest pain and muscle\nand joint pain but feels slightly short of breath.\nOn examination, he has central cyanosis, a\nblood pressure of 130/85 mmHg, a pulse of 110\nbpm, and a respiratory rate of 24 breaths per\nminute. He is afebrile. Pulse oximetry shows an\nO2 saturation of 86% while on room air. The\nrest of the exam, including a full neurological\nexam, is inconclusive. Which one of the\nfollowing is the next best step in management?","options":{"A":"Start intravenous heparin\nimmediately.","B":"Do a chest X-ray to confirm","C":"pulmonary embolism.","D":"an EGG.","E":"Do CTPA