INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('498fd1ebec57e3ae013c','AMEDEX 2025 HEMAETOLOGY (2).pdf','205','Mixed/Unclassified','A 45-year-old woman is evaluated as a part of
a routine health insurance medical
examination. The past medical history is
Significant for a gastric bypass surgery 12
years ago. Her blood test report is
remarkable for hemoglobin of 115 g/L
(normal 130-160g/L), an MCV of 110 fL
(normal 80-100 fL), and a platelet count of
110000/mm? (normal 150000-400000/mm?).
The reticulocyte count is 0.5% (normal in
