tatus":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["therapy"],"likely_visual_question":true,"parser_confidence":"medium","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"8b5af4b5687326a3bb9a7b3a61cf29801f84383b","duplicate_group_id":"exact-8b5af4b56873","duplicate_sources":[{"record_id":"07729b47c158012160fe","record_type":"text_mcq","source_file":"AMEDEX 2025 INFECTIOUS DISEASE (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 INFECTIOUS DISEASE (1).pdf","source_page":40,"source_qid":null},{"record_id":"10e1bd2a112573c26366","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":653,"source_qid":"405"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
