INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('f3a6cbacf74c5c166af0','AMEDEX 2025 INFECTIOUS DISEASE (1).pdf','42','Infectious Disease/Respiratory','A 47-year-old woman presents to your practice with complaints of fever, cough and hemoptysis. She is a nurse working in a rural area and has smoked 15 cigarettes a day for the past 20 years. She has also lost eight kg in the past three months. Her physical examination is unremarkable. A chest X-ray is obtained and shown in the accompanying photograph. Which one of the following is the most appropriate next step in management?','{"A":"Obtain sputum sample for Gram stain.","B":"Bronchoscopy and lavage.","C":"Obtain sputum sample for Ziehl-Neelsen stain.","D":"High-resolution CT scan of the chest.","E":"Start the patient on full-dose four-drug therapy for tuberculosis."}','C','Option C Is correct

Clinical findings of fever, cough, hemoptysis, and
weight loss, in the presence of a lesion seen in
the upper lobe of the right lung is highly
Suggestive of pulmonary tuberculosis (TB). This
patient should be considered to have TB unless
proven otherwise. When TB is suspected, the
next step will be obtaining three soutum
Samples for acid-fast (Zihel-Neelsen) bacilli
Staining and culture.

(Option A) Gram-stain does not show TB bacilli
and is not used for diagnosing TB.

(Option B) Bronchoscopy and lavage for
obtaining samples are indicated if traditionally-
obtained samples are negative but, based on
clinical grounds, TB is a likely diagnosis.

(Option D) High resolution CT scan of the chest
has no role in diagnosis of TB and is not
indicated unless the diagnosis is not certain or
other diagnoses than TB are considered..

(Option E) Starting the patient on full-dose 4-
drug therapy for tuberculosis is indicated in this
patient due to high possibility of TB as the
diagnosis, but it should be delayed until samples
are taken because antibiotics, if used prior to
testing, may alter test results, mostly in for

faise negativity.

