INSERT INTO questions (id,source_id,source_question_no,source_page,domain,system,topic,clinical_task,stem_en,stem_zh,answer_key,source_explanation_en,source_explanation_zh,memory_rule_en,memory_rule_zh,image_ref,source_year,import_version,active,options_mode,provenance_json,current_answer,current_answer_status,current_evidence_json,currentness_risk) VALUES ('f3a6cbacf74c5c166af0','src-v294-c8af63e7',NULL,'42','Infectious Disease/Respiratory','Infectious Disease/Respiratory','Infectious Disease/Respiratory','AMC MCQ','A 47-year-old woman presents to your practice with complaints of fever, cough and hemoptysis. She is a nurse working in a rural area and has smoked 15 cigarettes a day for the past 20 years. She has also lost eight kg in the past three months. Her physical examination is unremarkable. A chest X-ray is obtained and shown in the accompanying photograph. Which one of the following is the most appropriate next step in management?',NULL,'C','Option C Is correct

Clinical findings of fever, cough, hemoptysis, and
weight loss, in the presence of a lesion seen in
the upper lobe of the right lung is highly
Suggestive of pulmonary tuberculosis (TB). This
patient should be considered to have TB unless
proven otherwise. When TB is suspected, the
next step will be obtaining three soutum
Samples for acid-fast (Zihel-Neelsen) bacilli
Staining and culture.

(Option A) Gram-stain does not show TB bacilli
and is not used for diagnosing TB.

(Option B) Bronchoscopy and lavage for
obtaining samples are indicated if traditionally-
obtained samples are negative but, based on
clinical grounds, TB is a likely diagnosis.

(Option D) High resolution CT scan of the chest
has no role in diagnosis of TB and is not
indicated unless the diagnosis is not certain or
other diagnoses than TB are considered..

(Option E) Starting the patient on full-dose 4-
drug therapy for tuberculosis is indicated in this
patient due to high possibility of TB as the
diagnosis, but it should be delayed until samples
are taken because antibiotics, if used prior to
testing, may alter test results, mostly in for

faise negativity.

obtained samples are negative but, based on

clinical grounds, TB is a likely diagnosis.

(Option D) High resolution CT scan of the chest
has no role in diagnosis of TB and is not
indicated unless the diagnosis is not certain or
other diagnoses than TB are considered...

(Option E) Starting the patient on full-dose 4-
drug therapy for tuberculosis is indicated in this
patient due to high possibility of TB as the
diagnosis, but it should be delayed until samples
are taken because antibiotics, if used prior to
testing, may alter test results, mostly in form of
false negativity.

Reference(s) ° RACGP - Tuberculosis testing

¢ Australian Prescriber - Testing for
tuberculosis

- Therapeutic Guidelines - Antibiotic
S: available from http://tg.org.au

