INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('19eeaff237e4d74c6ce9','AMEDEX 2025 INFECTIOUS DISEASE (1).pdf','95','Infectious Disease','As part of a health check, an immigrant
Sudanese woman is found to have a positive
tuberculin skin test (TST). A chest X-ray is
obtained with inconclusive results. Soutum
microscopy and culture are positive for
tuberculosis (TB). She is planned to be started
on four-drug therapy. She has a 4-year-old son
and you make arrangements for him to have an
interferon gamma release assay (IGRA) which
turns out positive. The child is healthy and has
