INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('d38be9d7418cf6e6d137','AMEDEX 2025 INFECTIOUS DISEASE (2).pdf','62','Infectious Disease','A 60-year-old engineer was admitted to the
hospital with complaints of fever, cough and
pleuretic chest pain. On admission, he had a
fever of 40°C. Physical exam and chest X-ray
revealed right lower lobe pneumonia.
Sputum was obtained for smear and culture
that wa positive for pneumococcus. He was
Started on intravenous penicillin. After a few
days, fever and leukocytosis subsided and
chest X-ray showed clearing of the lobar
involvement. On the 7! day of admission,
his temperature spikes to 39.4 °C and his
dyspnea and cough worsens. A chest X-ray
Shows an increase in the pulmonary infiltrate.
Which one of the following is the most likely
