INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('7b6de6266d2f54ef02f8','AMEDEX 2025 INFECTIOUS DISEASE (2).pdf','83','Infectious Disease','The WCC of this patient does not make any of
the options least likely. A WCC count of 40/mm>
may be due to early bacterial meningitis, viral
meningitis, fungal meningitis or TB meningitis.
(Option A) In patients with partly treated
bacterial meningitiss culture and Gram stain
results may be altered (less frequently positive),
but other CSF values such as cell count, protein
and glucose remain mostly unchanged. With
elevated CSF protein and decreased CSF glucose,
bacterial meningitis can be likely despite a WCC
count of 40 with lymphocytic predominance.
(Option D) Carcinomatosis meningitis is a rare
complication of cancer in which the disease
Spreads to the meninges. It occurs in 5% of
patients with cancer, usually terminal. With
treatment, median survival is 2-3 months. CSF
analysis shows decreased glucose and elevated
protein levels as in this patient. However, no
cancer in the history and the rarity of the
condition make it less likely.
(Options D and E) CSF in fungal/TB meningitis
often has decreased glucose, increased protein
and cell count of 5-100 up to 500 cell/mm?','{"A":"> Back to exams","B":"IS A 1.6-2.5","C":"Glucose(mmol","D":"Usually normal","E":"/L) but may be normal but maybe normal\nGlucose:\nCSF serum <0.4 >0.6 <0.4\nratio\nwcc* >500 <1000\nGram stain Normal 60-90% positive Normal ee\nMonocytes\nOther 90% PMN 10% have >90% PMN\n30% have>50% PMN"}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 INFECTIOUS DISEASE (2).pdf","supporting_pages":[83,85],"source_qid":null,"duplicate_group_id":"exact-2bf0bbc577f5","duplicate_sources":[{"record_id":"7b6de6266d2f54ef02f8","record_type":"text_mcq","source_file":"AMEDEX 2025 INFECTIOUS DISEASE (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 INFECTIOUS DISEASE (2).pdf","source_page":83,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_cross_page_option_stitch","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"7b6de6266d2f54ef02f8","source_file":"AMEDEX 2025 INFECTIOUS DISEASE (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 INFECTIOUS DISEASE (2).pdf","source_year":2025,"source_page":83,"supporting_pages":[83,85],"source_qid":null,"domain_hint":"Infectious Disease","stem":"The WCC of this patient does not make any of\nthe options least likely. A WCC count of 40/mm>\nmay be due to early bacterial meningitis, viral\nmeningitis, fungal meningitis or TB meningitis.\n(Option A) In patients with partly treated\nbacterial meningitiss culture and Gram stain\nresults may be altered (less frequently positive),\nbut other CSF values such as cell count, protein\nand glucose remain mostly unchanged. With\nelevated CSF protein and decreased CSF glucose,\nbacterial meningitis can be likely despite a WCC\ncount of 40 with lymphocytic predominance.\n(Option D) Carcinomatosis meningitis is a rare\ncomplication of cancer in which the disease\n