INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('81c0a455abe42cbec84d','AMEDEX 2025 INFECTIOUS DISEASE (2).pdf','136','Infectious Disease','Jarred, three years old, was brought to your
clinic by his mother with a complaint of a non-
healing abscess in his neck. It started with a
painless lymph node enlargement in the left
submandibular area, which gradually developed
into an abscess over a few weeks. A 5-day
course of oral amoxicillin prescribed by another
doctor failed to treat the abscess. Which of the
following would be the most appropriate
