INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('c83f40463e1027622e01','AMEDEX 2025 INFECTIOUS DISEASE (2).pdf','172','Infectious Disease','A 40-year-old man presents to the emergency
department with complaints of fever and cough.
He has the history of chronic cough and sputum
for the past 2 years. According to him, the
sputum is greenish-yellow and very copious
especially in the morning. He mentions that he
almost has had a cup-full of soutum every days
for the past several months. On examination, he
has a blood pressure of 110/95mmbHg, pulse
rate of 110bpm, temperature of 38.7, and O2
saturation of 92% while on room air. Lung
auscultation reveals consolidation of the right
lower lobe and bibasal crackles. A chest x-ray
establish the diagnosis of lobar pneumonia.
Which one of the following is the most
appropriate treatment option for him?','{"A":"Oral roxythromycin.","B":"Oral Augmentin.","C":"Intravenous ampicillin.","D":"Intravenous flucloxacillin.","E":"Intravenous piperacillin-tazobactam."}','E',NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 INFECTIOUS DISEASE (2).pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-e05afc32d96f","duplicate_sources":[{"record_id":"c83f40463e1027622e01","record_type":"text_mcq","source_file":"AMEDEX 2025 INFECTIOUS DISEASE (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 INFECTIOUS DISEASE (2).pdf","source_page":172,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"c83f40463e1027622e01","source_file":"AMEDEX 2025 INFECTIOUS DISEASE (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 INFECTIOUS DISEASE (2).pdf","source_year":2025,"source_page":172,"source_qid":null,"domain_hint":"Infectious Disease","stem":"A 40-year-old man presents to the emergency\ndepartment with complaints of fever and cough.\nHe has the history of chronic cough and sputum\nfor the past 2 years. According to him, the\nsputum is greenish-yellow and very copious\nespecially in the morning. He mentions that he\nalmost has had a cup-full of soutum every days\nfor the past several months. On examination, he\nhas a blood pressure of 110/95mmbHg, pulse\nrate of 110bpm, temperature of 38.7, and O2\nsaturation of 92% while on room air. Lung\nauscultation reveals consolidation of the right\nlower lobe and bibasal crackles. A chest x-ray\nestablish the diagnosis of lobar pneumonia.\nWhich one of the following is the most\nappropriate treatment option for him?","options":{"A":"Oral roxythromycin.","B":"Oral Augmentin.","C":"Intravenous ampicillin.","D":"Intravenous flucloxacilli