INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('a411ff1fefb6df779422','AMEDEX 2025 NEUROLOGY (1).pdf','11','Neurology','A 65-year-old woman presents to the
emergency department with complaint of
difficulty walking for the past 24 hours. She also
mentions that she has been experiencing
progressive pins and needles in hands and feet
for the past few days. On examination, she has
a blood pressure of 130/80 mmHg, pulse rate of
90 bpm, respiratory rate of 14 breaths per
minute and temperature of 37.5°C. On
neurological examination, she is found to have
brisk deep tendon reflexes (DTRs). There is an
extensor plantar response. There Is also a
decrease in sensing pain, temperature, vibration
and touch. Romberg test is positive. There is no
visual sign or symptom. Which one of the
following is the investigation of choice to reach
a diagnosis?','{"A":"Lumbar puncture.","B":"Nerve conduction studies.","C":"Serum vitamin B12 level.","D":"Serum creatine kinase (Ck).","E":"— MRI of the brain. ©"}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (1).pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-0b8340a078cd","duplicate_sources":[{"record_id":"a411ff1fefb6df779422","record_type":"text_mcq","source_file":"AMEDEX 2025 NEUROLOGY (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (1).pdf","source_page":11,"source_qid":null},{"record_id":"14af49bd943abbe7185a","record_type":"text_mcq","source_file":"AMEDEX 2025 NEUROLOGY (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (1).pdf","source_page":10,"source_qid":null},{"record_id":"d0d07444b9e0c3872f26","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":715,"source_qid":"802"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"a411ff1fefb6df779422","source_file":"AMEDEX 2025 NEUROLOGY (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (1).pdf","source_year":2025,"source_page":11,"source_qid":null,"domain_hint":"Neurology","stem":"A 65-year-old woman presents to the\nemergency department with complaint of\ndifficulty walking for the past 24 hours. She also\nmentions that she has been experiencing\nprogressive pins and needles in hands and feet\nfor the past few days. On examination, she has\na blood pressure of 130/80 mmHg, pulse rate of\n90 bpm, respiratory rate of 14 breaths per\nminute and temperature of 37.5°C. On\nneurological examination, she is found to have\nbrisk deep tendon reflexes (DTRs). There is an\nextensor plantar response.