INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('ac1ea6e4f355d1c17c0e','AMEDEX 2025 NEUROLOGY (1).pdf','14','Neurology','A 71-year-old man presents to your GP practice
3 days after a head injury. You review this
patient’s records and find that he had consulted
your practice on the day of the injury and was
noted to have an initially normal neurologic
physical exam with mild pain resolved with
paracetamol. Now, he complains of occasional
headaches, dizziness, and left-sided blindness
described as “seeing only half of the right side”
in each eye. You perform a physical exam that
confirms your findings. Where is the most likely
site of the lesion?','{"A":"Right optic nerve.","B":"Left optic tract.","C":"G Right optic tract.","D":"Right occipital cortex.","E":"s Right parietal cortex."}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (1).pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-b2e7eafa9427","duplicate_sources":[{"record_id":"ac1ea6e4f355d1c17c0e","record_type":"text_mcq","source_file":"AMEDEX 2025 NEUROLOGY (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (1).pdf","source_page":14,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"ac1ea6e4f355d1c17c0e","source_file":"AMEDEX 2025 NEUROLOGY (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (1).pdf","source_year":2025,"source_page":14,"source_qid":null,"domain_hint":"Neurology","stem":"A 71-year-old man presents to your GP practice\n3 days after a head injury. You review this\npatient’s records and find that he had consulted\nyour practice on the day of the injury and was\nnoted to have an initially normal neurologic\nphysical exam with mild pain resolved with\nparacetamol. Now, he complains of occasional\nheadaches, dizziness, and left-sided blindness\ndescribed as “seeing only half of the right side”\nin each eye. You perform a physical exam that\nconfirms your findings. Where is the most likely\nsite of the lesion?","options":{"A":"Right optic nerve.","B":"Left optic tract.","C":"G Right optic tract.","D":"Right occipital cortex.","E":"s Right parietal cortex."},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_questi