INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('7a8cba6cbbe562284f8d','AMEDEX 2025 NEUROLOGY (1).pdf','32','Neurology','Alan, 45 years, is a new patient to your clinic.
He has presented with complaint of frequent
tripping of his right foot for the past few months,
which has increased in frequency in the past
month. On examination, interosseous muscles
wasting of the right foot is noted. Plantar reflex
is equivocal on the right but extensor on the left.
Lower limb deep tendon reflexes are normal.
There is foot drop on the right side. Which one
